window.GENERATED_MODULES = window.GENERATED_MODULES || [];
window.GENERATED_MODULES.push(.../*__DATA_START__*/[{"id":"gen-lang-en-english-history-of-literature-language-mtjzy8nb","subject":"lang-en","day":51,"level":1,"title":"History of English Literature & Language","hi":"अंग्रेज़ी साहित्य और भाषा का इतिहास","concepts":[{"title":"Key Periods and Writers","title_hi":"प्रमुख काल और लेखक","simple":"English literature has changed over time, and each period has famous writers.","simple_hi":"अंग्रेज़ी साहित्य समय के साथ बदला है, और हर काल के प्रसिद्ध लेखक हैं।","intro":"","points":["Old English (450-1100 AD): 'Beowulf' is a famous epic poem. (पुरानी अंग्रेज़ी: 'बियोवुल्फ़' प्रसिद्ध महाकाव्य है।)","Middle English (1100-1500): Geoffrey Chaucer wrote 'The Canterbury Tales'. (मध्य अंग्रेज़ी: जेफ्री चौसर ने 'द कैंटरबरी टेल्स' लिखा।)","Renaissance (1500-1660): William Shakespeare wrote plays and sonnets. (पुनर्जागरण: विलियम शेक्सपियर ने नाटक और सॉनेट लिखे।)","Romantic Age (1798-1837): William Wordsworth and S.T. Coleridge are key poets. (रोमांटिक काल: विलियम वर्ड्सवर्थ और एस.टी. कोलरिज प्रमुख कवि हैं।)","Victorian Age (1837-1901): Charles Dickens wrote novels like 'Oliver Twist'. (विक्टोरियन काल: चार्ल्स डिकेंस ने 'ओलिवर ट्विस्ट' जैसे उपन्यास लिखे।)"],"example":"If you read 'Beowulf', you are reading Old English. It was written around 1000 AD. The language is very different from today's English. (यदि आप 'बियोवुल्फ़' पढ़ते हैं, तो आप पुरानी अंग्रेज़ी पढ़ रहे हैं। यह लगभग 1000 ई. में लिखा गया था। भाषा आज की अंग्रेज़ी से बहुत अलग है।)","trick":"Remember 'O M R V' – Old, Middle, Renaissance, Victorian. (याद रखें 'ओ एम आर वी' – ओल्ड, मिडल, रेनेसाँ, विक्टोरियन।)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"The history of English is divided into periods based on language change and historical events. For example, the Norman Conquest in 1066 brought French influence, leading to Middle English. The Renaissance revived classical learning. The Romantic Age reacted against industrialization. Knowing these periods helps answer questions about authors and their works. (अंग्रेज़ी का इतिहास भाषा परिवर्तन और ऐतिहासिक घटनाओं के आधार पर विभाजित है। उदाहरण के लिए, 1066 में नॉर्मन विजय ने फ्रेंच प्रभाव लाया, जिससे मध्य अंग्रेज़ी बनी। पुनर्जागरण ने शास्त्रीय ज्ञान को पुनर्जीवित किया। रोमांटिक काल ने औद्योगीकरण के खिलाफ प्रतिक्रिया दी। इन कालों को जानने से लेखकों और उनकी रचनाओं के प्रश्नों में मदद मिलती है।)","body_hi":"The history of English is divided into periods based on language change and historical events. For example, the Norman Conquest in 1066 brought French influence, leading to Middle English. The Renaissance revived classical learning. The Romantic Age reacted against industrialization. Knowing these periods helps answer questions about authors and their works. (अंग्रेज़ी का इतिहास भाषा परिवर्तन और ऐतिहासिक घटनाओं के आधार पर विभाजित है। उदाहरण के लिए, 1066 में नॉर्मन विजय ने फ्रेंच प्रभाव लाया, जिससे मध्य अंग्रेज़ी बनी। पुनर्जागरण ने शास्त्रीय ज्ञान को पुनर्जीवित किया। रोमांटिक काल ने औद्योगीकरण के खिलाफ प्रतिक्रिया दी। इन कालों को जानने से लेखकों और उनकी रचनाओं के प्रश्नों में मदद मिलती है।)"}}],"questions":[{"q":"Who is known as the 'Father of English Literature'?","q_hi":"किसे 'अंग्रेज़ी साहित्य का जनक' कहा जाता है?","o":["William Shakespeare","Geoffrey Chaucer","John Milton","Charles Dickens"],"o_hi":["विलियम शेक्सपियर","जेफ्री चौसर","जॉन मिल्टन","चार्ल्स डिकेंस"],"a":1,"exp":"Geoffrey Chaucer is called the 'Father of English Literature' because he wrote 'The Canterbury Tales' in Middle English and helped establish English as a literary language.","exp_hi":"जेफ्री चौसर को 'अंग्रेज़ी साहित्य का जनक' कहा जाता है क्योंकि उन्होंने मध्य अंग्रेज़ी में 'द कैंटरबरी टेल्स' लिखी और अंग्रेज़ी को साहित्यिक भाषा के रूप में स्थापित करने में मदद की।","why":["शेक्सपियर बाद के पुनर्जागरण काल के हैं, इसलिए वे 'जनक' नहीं हैं।","मिल्टन 17वीं सदी के हैं, चौसर से बहुत बाद में।","डिकेंस विक्टोरियन काल के हैं, इसलिए वे 'जनक' नहीं हो सकते।"],"topic":"History of Literature","level":1,"mode":"standard"},{"q":"Which epic poem is written in Old English?","q_hi":"कौन-सा महाकाव्य पुरानी अंग्रेज़ी में लिखा गया है?","o":["Paradise Lost","The Canterbury Tales","Beowulf","The Faerie Queene"],"o_hi":["पैराडाइज़ लॉस्ट","द कैंटरबरी टेल्स","बियोवुल्फ़","द फेयरी क्वीन"],"a":2,"exp":"Beowulf is the most famous Old English epic poem. It was written around 1000 AD.","exp_hi":"बियोवुल्फ़ सबसे प्रसिद्ध पुरानी अंग्रेज़ी महाकाव्य है। यह लगभग 1000 ई. में लिखा गया था।","why":["पैराडाइज़ लॉस्ट जॉन मिल्टन द्वारा 17वीं सदी में लिखा गया, यह आधुनिक अंग्रेज़ी में है।","द कैंटरबरी टेल्स मध्य अंग्रेज़ी में है, पुरानी नहीं।","द फेयरी क्वीन एडमंड स्पेंसर द्वारा पुनर्जागरण काल में लिखी गई, यह आधुनिक अंग्रेज़ी के करीब है।"],"topic":"Old English Literature","level":1,"mode":"standard"},{"q":"Which literary period is known as the 'Golden Age of English Drama'?","q_hi":"कौन-सा साहित्यिक काल 'अंग्रेज़ी नाटक का स्वर्ण युग' कहलाता है?","o":["The Romantic Age","The Victorian Age","The Renaissance","The Modern Age"],"o_hi":["रोमांटिक काल","विक्टोरियन काल","पुनर्जागरण","आधुनिक काल"],"a":2,"exp":"The Renaissance (16th-17th century) is called the Golden Age of English Drama because of playwrights like Shakespeare and Marlowe.","exp_hi":"पुनर्जागरण (16वीं-17वीं शताब्दी) को अंग्रेज़ी नाटक का स्वर्ण युग कहा जाता है क्योंकि शेक्सपियर और मार्लो जैसे नाटककार थे।","why":["रोमांटिक काल कविता के लिए प्रसिद्ध है, नाटक के लिए नहीं।","विक्टोरियन काल उपन्यासों के लिए जाना जाता है।","आधुनिक काल में नाटक कम प्रमुख थे।"],"topic":"Renaissance Drama","level":2,"mode":"standard"},{"q":"Who wrote 'Paradise Lost'?","q_hi":"'पैराडाइज़ लॉस्ट' किसने लिखी?","o":["John Milton","William Wordsworth","Alexander Pope","John Dryden"],"o_hi":["जॉन मिल्टन","विलियम वर्ड्सवर्थ","अलेक्जेंडर पोप","जॉन ड्राइडन"],"a":0,"exp":"John Milton wrote the epic poem 'Paradise Lost' in 1667. It tells the story of the fall of man.","exp_hi":"जॉन मिल्टन ने 1667 में महाकाव्य 'पैराडाइज़ लॉस्ट' लिखी। यह मनुष्य के पतन की कहानी है।","why":["वर्ड्सवर्थ रोमांटिक काल के कवि हैं, उन्होंने यह नहीं लिखा।","पोप 18वीं सदी के कवि हैं, यह उनकी रचना नहीं है।","ड्राइडन भी बाद के कवि हैं, यह उनकी रचना नहीं है।"],"topic":"Milton","level":1,"mode":"standard"},{"q":"Which of the following pairs is correctly matched?","q_hi":"निम्नलिखित में से कौन-सा युग्म सही सुमेलित है?","o":["William Wordsworth – 'The Prelude'","Charles Dickens – 'Pride and Prejudice'","Jane Austen – 'Oliver Twist'","T.S. Eliot – 'The Canterbury Tales'"],"o_hi":["विलियम वर्ड्सवर्थ – 'द प्रील्यूड'","चार्ल्स डिकेंस – 'प्राइड एंड प्रेजुडिस'","जेन ऑस्टिन – 'ओलिवर ट्विस्ट'","टी.एस. इलियट – 'द कैंटरबरी टेल्स'"],"a":0,"exp":"Wordsworth wrote 'The Prelude', an autobiographical poem. The others are mismatched: Dickens wrote 'Oliver Twist', Austen wrote 'Pride and Prejudice', and Chaucer wrote 'The Canterbury Tales'.","exp_hi":"वर्ड्सवर्थ ने आत्मकथात्मक कविता 'द प्रील्यूड' लिखी। अन्य गलत हैं: डिकेंस ने 'ओलिवर ट्विस्ट', ऑस्टिन ने 'प्राइड एंड प्रेजुडिस', और चौसर ने 'द कैंटरबरी टेल्स' लिखी।","why":["डिकेंस ने 'ओलिवर ट्विस्ट' लिखा, 'प्राइड एंड प्रेजुडिस' नहीं।","जेन ऑस्टिन ने 'प्राइड एंड प्रेजुडिस' लिखा, 'ओलिवर ट्विस्ट' नहीं।","टी.एस. इलियट ने 'द कैंटरबरी टेल्स' नहीं लिखी; यह चौसर की है।"],"topic":"Author-Work Matching","level":2,"mode":"standard"}]},{"id":"gen-lang-en-english-grammar-mtjzyi7r","subject":"lang-en","day":52,"level":1,"title":"English Grammar Basics","hi":"अंग्रेज़ी व्याकरण की मूल बातें","concepts":[{"title":"Parts of Speech","title_hi":"शब्द-भेद","simple":"Parts of speech are the different jobs words do in a sentence.","simple_hi":"शब्द-भेद वाक्य में शब्दों के अलग-अलग काम हैं।","intro":"","points":["Noun (संज्ञा): names a person, place, thing, or idea – राम, school, happiness.","Pronoun (सर्वनाम): replaces a noun – he, she, it, they.","Verb (क्रिया): shows action or state – run, is, feel.","Adjective (विशेषण): describes a noun – red, tall, beautiful.","Adverb (क्रिया-विशेषण): describes a verb, adjective, or another adverb – quickly, very, well.","Preposition (संबंध-सूचक): shows relationship – in, on, under."],"example":"In the sentence 'The quick brown fox jumps over the lazy dog' – 'fox' and 'dog' are nouns, 'quick' and 'lazy' are adjectives, 'jumps' is a verb, 'over' is a preposition, and 'the' is an article.","trick":"Remember 'N.V.A.A.P.P.' – N for Noun, V for Verb, A for Adjective, A for Adverb, P for Preposition, P for Pronoun (and add C for Conjunction, I for Interjection).","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"Words can change their part of speech based on context. For example, 'run' is a verb in 'I run fast' but a noun in 'I went for a run'. In the exam, always look at how the word is used in the sentence, not just its dictionary meaning.","body_hi":"Words can change their part of speech based on context. For example, 'run' is a verb in 'I run fast' but a noun in 'I went for a run'. In the exam, always look at how the word is used in the sentence, not just its dictionary meaning."}}],"questions":[{"q":"Which word in the following sentence is an adverb? 'She sings very sweetly.'","q_hi":"निम्नलिखित वाक्य में कौन-सा शब्द क्रिया-विशेषण (adverb) है? 'She sings very sweetly.'","o":["sings","very","sweetly","She"],"o_hi":["sings","very","sweetly","She"],"a":2,"exp":"An adverb modifies a verb, adjective, or another adverb. Here, 'sweetly' tells how she sings (modifying the verb 'sings'), so it is the adverb.","exp_hi":"क्रिया-विशेषण क्रिया, विशेषण या किसी अन्य क्रिया-विशेषण की विशेषता बताता है। यहाँ 'sweetly' बताता है कि वह कैसे गाती है (क्रिया 'sings' की विशेषता), इसलिए यह क्रिया-विशेषण है।","why":["'sings' is a verb (क्रिया), not an adverb.","'very' is an adverb that modifies 'sweetly', but the question asks for the word that directly tells how she sings – 'sweetly' is the main adverb.","'She' is a pronoun (सर्वनाम), not an adverb."],"topic":"Adverb identification","level":1,"mode":"standard"},{"q":"Choose the correct pronoun to fill in the blank: 'Ravi and ______ went to the market.'","q_hi":"रिक्त स्थान के लिए सही सर्वनाम चुनें: 'Ravi and ______ went to the market.'","o":["me","I","myself","mine"],"o_hi":["me","I","myself","mine"],"a":1,"exp":"The pronoun is part of the subject (Ravi and I went). Subject pronouns are I, you, he, she, it, we, they. So 'I' is correct.","exp_hi":"सर्वनाम कर्ता (subject) का हिस्सा है (Ravi and I went)। कर्ता सर्वनाम हैं: I, you, he, she, it, we, they। इसलिए 'I' सही है।","why":["'me' is an object pronoun (कर्म सर्वनाम) – it is used after a verb or preposition, not as part of the subject.","'myself' is a reflexive pronoun (निजवाचक) used when the subject and object are the same, e.g., 'I hurt myself'.","'mine' is a possessive pronoun (अधिकारवाचक) meaning 'my thing', e.g., 'This book is mine'."],"topic":"Pronoun case","level":2,"mode":"standard"},{"q":"Identify the adjective in the sentence: 'The tall building has many windows.'","q_hi":"वाक्य में विशेषण पहचानें: 'The tall building has many windows.'","o":["building","tall","windows","has"],"o_hi":["building","tall","windows","has"],"a":1,"exp":"An adjective describes a noun. 'Tall' describes the noun 'building', so it is the adjective.","exp_hi":"विशेषण संज्ञा की विशेषता बताता है। 'Tall' संज्ञा 'building' की विशेषता बता रहा है, इसलिए यह विशेषण है।","why":["'building' is a noun (संज्ञा), not an adjective.","'windows' is a noun (संज्ञा), not an adjective.","'has' is a verb (क्रिया), not an adjective."],"topic":"Adjective identification","level":1,"mode":"standard"},{"q":"Choose the correct preposition: 'The cat is hiding ______ the bed.'","q_hi":"सही संबंध-सूचक चुनें: 'The cat is hiding ______ the bed.'","o":["on","under","in","at"],"o_hi":["on","under","in","at"],"a":1,"exp":"To hide under something means to be beneath it. A cat hiding under the bed is a common situation, and 'under' shows the position below the bed.","exp_hi":"किसी चीज़ के नीचे छिपना 'under' से दर्शाया जाता है। बिल्ली का बिस्तर के नीचे छिपना सामान्य है, और 'under' बिस्तर के नीचे की स्थिति दर्शाता है।","why":["'on' means on top of the surface – a cat could sit on the bed, but hiding 'on' the bed is not typical.","'in' means inside – a cat might be in the bed (between sheets), but 'under' is more natural for hiding beneath.","'at' is used for a point or location, not for a relationship like under something."],"topic":"Prepositions","level":1,"mode":"standard"},{"q":"Which sentence uses the verb correctly?","q_hi":"किस वाक्य में क्रिया का सही प्रयोग हुआ है?","o":["She go to school.","She goes to school.","She going to school.","She gone to school."],"o_hi":["She go to school.","She goes to school.","She going to school.","She gone to school."],"a":1,"exp":"With a third-person singular subject (she/he/it), the present simple verb takes an -s. So 'goes' is correct.","exp_hi":"तीसरे व्यक्ति एकवचन कर्ता (she/he/it) के साथ वर्तमान काल की क्रिया में 's' जुड़ता है। इसलिए 'goes' सही है।","why":["'go' is used with plural subjects or I/you – 'She go' is incorrect.","'going' needs a helping verb like 'is' – 'She is going' would be correct.","'gone' is the past participle and needs a helping verb – 'She has gone' would be correct."],"topic":"Subject-verb agreement","level":2,"mode":"standard"}]},{"id":"gen-lang-en-english-revision-practice-mtqv2qpg","subject":"lang-en","day":55,"level":1,"title":"English — Revision + Practice","hi":"अंग्रेज़ी — पुनरावृत्ति + अभ्यास","concepts":[{"title":"Revision and Practice","title_hi":"पुनरावृत्ति और अभ्यास","simple":"Revision means going over what you have learned to remember it better.","simple_hi":"पुनरावृत्ति का मतलब है जो आपने सीखा है उसे दोबारा पढ़ना ताकि वह अच्छे से याद रहे।","intro":"","points":["Revision helps you remember facts, grammar rules, and vocabulary for exams. (पुनरावृत्ति से परीक्षा के लिए तथ्य, व्याकरण के नियम और शब्दावली याद रहती है।)","Practice means solving questions and exercises to apply what you have learned. (अभ्यास का अर्थ है प्रश्नों और अभ्यासों को हल करके सीखी हुई बातों को लागू करना।)","In English, revision includes grammar (parts of speech, tenses, punctuation), literature (authors, poets, stories), and comprehension (reading passages). (अंग्रेज़ी में पुनरावृत्ति में व्याकरण—शब्द-भेद, काल, विराम चिह्न—साहित्य—लेखक, कवि, कहानियाँ—और बोध (गद्यांश) शामिल हैं।)","Famous English writers: William Shakespeare, Charles Dickens, Rabindranath Tagore (wrote in English too), R.K. Narayan. (प्रसिद्ध अंग्रेज़ी लेखक: विलियम शेक्सपियर, चार्ल्स डिकेंस, रवींद्रनाथ टैगोर (अंग्रेज़ी में भी लिखा), आर.के. नारायण।)","Common grammar topics: noun, pronoun, verb, adjective, adverb, preposition, conjunction, tense, voice, narration. (सामान्य व्याकरण विषय: संज्ञा, सर्वनाम, क्रिया, विशेषण, क्रिया-विशेषण, संबंधसूचक, समुच्चयबोधक, काल, वाच्य, कथन।)"],"example":"Example: To revise the present tense, you make sentences: 'I go to school.' (present simple), 'I am going to school.' (present continuous). Practice by changing the verb: 'She goes', 'She is going'. This helps you remember the rules. (उदाहरण: वर्तमान काल की पुनरावृत्ति के लिए वाक्य बनाएँ: 'I go to school.' (सामान्य वर्तमान), 'I am going to school.' (अपूर्ण वर्तमान)। अभ्यास करें क्रिया बदलकर: 'She goes', 'She is going'। इससे नियम याद रहते हैं।)","trick":"Use the mnemonic 'FANBOYS' to remember coordinating conjunctions: For, And, Nor, But, Or, Yet, So. (संयोजक समुच्चयबोधक याद रखने के लिए 'FANBOYS' स्मरण युक्ति: For, And, Nor, But, Or, Yet, So।)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"In the exam, you will face questions that mix grammar and literature. For example, you may be asked to identify the correct tense form in a sentence from a famous story, or to match a poet with his work. A common trap is confusing 'its' (possessive) with 'it's' (it is). Also, remember that 'Shakespeare' wrote plays like 'Romeo and Juliet' and sonnets, while 'Dickens' wrote novels like 'Oliver Twist'. Practice with previous year questions to get familiar with the pattern. (परीक्षा में व्याकरण और साहित्य मिले-जुले प्रश्न आते हैं। उदाहरण के लिए, किसी प्रसिद्ध कहानी के वाक्य में सही काल पहचानना या कवि को उसकी रचना से मिलाना। एक सामान्य भ्रम है 'its' (संबंधवाचक) और 'it's' (it is) में। यह भी याद रखें कि 'शेक्सपियर' ने नाटक लिखे जैसे 'रोमियो और जूलियट' और सॉनेट, जबकि 'डिकेंस' ने उपन्यास लिखे जैसे 'ओलिवर ट्विस्ट'। पिछले वर्षों के प्रश्नों का अभ्यास करें।)","body_hi":"In the exam, you will face questions that mix grammar and literature. For example, you may be asked to identify the correct tense form in a sentence from a famous story, or to match a poet with his work. A common trap is confusing 'its' (possessive) with 'it's' (it is). Also, remember that 'Shakespeare' wrote plays like 'Romeo and Juliet' and sonnets, while 'Dickens' wrote novels like 'Oliver Twist'. Practice with previous year questions to get familiar with the pattern. (परीक्षा में व्याकरण और साहित्य मिले-जुले प्रश्न आते हैं। उदाहरण के लिए, किसी प्रसिद्ध कहानी के वाक्य में सही काल पहचानना या कवि को उसकी रचना से मिलाना। एक सामान्य भ्रम है 'its' (संबंधवाचक) और 'it's' (it is) में। यह भी याद रखें कि 'शेक्सपियर' ने नाटक लिखे जैसे 'रोमियो और जूलियट' और सॉनेट, जबकि 'डिकेंस' ने उपन्यास लिखे जैसे 'ओलिवर ट्विस्ट'। पिछले वर्षों के प्रश्नों का अभ्यास करें।)"}}],"questions":[{"q":"Which of the following is a correct sentence in the present continuous tense?","q_hi":"निम्नलिखित में से कौन-सा वाक्य वर्तमान अपूर्ण काल में सही है?","o":["She is reading a book.","She reads a book.","She read a book.","She has read a book."],"o_hi":["वह किताब पढ़ रही है।","वह किताब पढ़ती है।","वह किताब पढ़ी।","वह किताब पढ़ चुकी है।"],"a":0,"exp":"The present continuous tense is formed with 'is/am/are' + verb-ing. 'She is reading' shows an action happening now.","exp_hi":"वर्तमान अपूर्ण काल 'is/am/are' + क्रिया का '-ing' रूप से बनता है। 'She is reading' अभी हो रही क्रिया दर्शाता है।","why":["'She reads a book.' is simple present tense, used for habits or routines, not for action happening now. (यह सामान्य वर्तमान काल है, आदत या नियमित क्रिया के लिए, अभी हो रही क्रिया के लिए नहीं।)","'She read a book.' is simple past tense, indicating a completed action in the past. (यह सामान्य भूतकाल है, भूत में पूरी हुई क्रिया।)","'She has read a book.' is present perfect tense, showing an action completed recently or with present relevance. (यह पूर्ण वर्तमान काल है, हाल में पूरी हुई या वर्तमान से संबंधित क्रिया।)"],"topic":"Tenses","level":1,"mode":"standard"},{"q":"Who wrote the famous play 'Romeo and Juliet'?","q_hi":"प्रसिद्ध नाटक 'रोमियो और जूलियट' किसने लिखा?","o":["William Wordsworth","William Shakespeare","Charles Dickens","John Keats"],"o_hi":["विलियम वर्ड्सवर्थ","विलियम शेक्सपियर","चार्ल्स डिकेंस","जॉन कीट्स"],"a":1,"exp":"William Shakespeare is the renowned playwright who wrote 'Romeo and Juliet', a tragedy about two young lovers.","exp_hi":"विलियम शेक्सपियर प्रसिद्ध नाटककार हैं जिन्होंने 'रोमियो और जूलियट' लिखा, जो दो युवा प्रेमियों की त्रासदी है।","why":["William Wordsworth was a Romantic poet, known for poems like 'Daffodils', not for plays. (विलियम वर्ड्सवर्थ रोमांटिक कवि थे, 'डैफोडिल्स' जैसी कविताओं के लिए जाने जाते हैं, नाटकों के लिए नहीं।)","Charles Dickens was a novelist, famous for 'Oliver Twist' and 'A Christmas Carol', not a playwright. (चार्ल्स डिकेंस उपन्यासकार थे, 'ओलिवर ट्विस्ट' और 'अ क्रिसमस कैरल' के लिए प्रसिद्ध, नाटककार नहीं।)","John Keats was a Romantic poet, known for odes like 'Ode to a Nightingale', not for plays. (जॉन कीट्स रोमांटिक कवि थे, 'ओड टू अ नाइटिंगेल' जैसी कविताओं के लिए, नाटकों के लिए नहीं।)"],"topic":"English Literature","level":1,"mode":"standard"},{"q":"Choose the correct plural form of the word 'child'.","q_hi":"'child' शब्द का सही बहुवचन रूप चुनें।","o":["childs","children","childes","childrens"],"o_hi":["चाइल्ड्स","चिल्ड्रन","चाइल्डेस","चिल्ड्रन्स"],"a":1,"exp":"The plural of 'child' is 'children'. It is an irregular plural noun.","exp_hi":"'child' का बहुवचन 'children' होता है। यह अनियमित बहुवचन संज्ञा है।","why":["'childs' is not correct because 'child' does not take 's' to form plural; it is irregular. ('childs' गलत है क्योंकि 'child' बहुवचन बनाने के लिए 's' नहीं लेता; यह अनियमित है।)","'childes' is not a word in English; the correct form is 'children'. ('childes' अंग्रेज़ी में शब्द नहीं है; सही रूप 'children' है।)","'childrens' is incorrect because 'children' is already plural; adding 's' makes it double plural. ('childrens' गलत है क्योंकि 'children' पहले से बहुवचन है; 's' जोड़ने से दोहरा बहुवचन बनता है।)"],"topic":"Nouns","level":1,"mode":"standard"},{"q":"Read the passage: 'The sun rises in the east. It gives us light and warmth. Plants need sunlight to make food.' What is the main idea of the passage?","q_hi":"गद्यांश पढ़ें: 'सूर्य पूर्व में उगता है। यह हमें प्रकाश और गर्मी देता है। पौधों को भोजन बनाने के लिए सूर्य की रोशनी चाहिए।' गद्यांश का मुख्य विचार क्या है?","o":["The sun is very hot.","The sun is important for life on Earth.","The sun rises in the west.","Plants do not need sunlight."],"o_hi":["सूर्य बहुत गर्म है।","पृथ्वी पर जीवन के लिए सूर्य महत्वपूर्ण है।","सूर्य पश्चिम में उगता है।","पौधों को सूर्य की रोशनी नहीं चाहिए।"],"a":1,"exp":"The passage explains that the sun gives light, warmth, and helps plants make food, so the main idea is that the sun is important for life.","exp_hi":"गद्यांश बताता है कि सूर्य प्रकाश, गर्मी देता है और पौधों को भोजन बनाने में मदद करता है, इसलिए मुख्य विचार है कि सूर्य जीवन के लिए महत्वपूर्ण है।","why":["The passage does not focus on the sun being hot; it mentions warmth but not as the main idea. (गद्यांश सूर्य के गर्म होने पर केंद्रित नहीं है; गर्मी का उल्लेख है पर मुख्य विचार नहीं।)","The passage clearly says the sun rises in the east, not the west, so this option contradicts the text. (गद्यांश स्पष्ट कहता है सूर्य पूर्व में उगता है, पश्चिम में नहीं, इसलिए यह विकल्प पाठ के विपरीत है।)","The passage states that plants need sunlight to make food, so saying they do not need sunlight is false. (गद्यांश कहता है पौधों को भोजन बनाने के लिए सूर्य की रोशनी चाहिए, इसलिए यह कहना कि उन्हें रोशनी नहीं चाहिए, गलत है।)"],"topic":"Reading Comprehension","level":1,"mode":"standard"},{"q":"Which sentence uses the correct punctuation?","q_hi":"कौन-सा वाक्य सही विराम चिह्न का प्रयोग करता है?","o":["What a beautiful day","What a beautiful day!","What a beautiful day?","What a beautiful day."],"o_hi":["कितना सुंदर दिन","कितना सुंदर दिन!","कितना सुंदर दिन?","कितना सुंदर दिन।"],"a":1,"exp":"An exclamatory sentence expresses strong emotion, so it should end with an exclamation mark (!).","exp_hi":"विस्मयादिबोधक वाक्य प्रबल भावना व्यक्त करता है, इसलिए उसके अंत में विस्मयादिबोधक चिह्न (!) होना चाहिए।","why":["Without any punctuation, it is not a complete sentence. (बिना किसी विराम चिह्न के यह पूर्ण वाक्य नहीं है।)","A question mark is used for questions, but this is an exclamation, not a question. (प्रश्नवाचक चिह्न प्रश्नों के लिए होता है, पर यह विस्मयादिबोधक है, प्रश्न नहीं।)","A full stop is used for statements, but this sentence expresses excitement, so exclamation mark is correct. (पूर्ण विराम कथनों के लिए होता है, पर यह वाक्य उत्साह व्यक्त करता है, इसलिए विस्मयादिबोधक चिह्न सही है।)"],"topic":"Punctuation","level":1,"mode":"standard"},{"q":"Choose the word that is a synonym of 'happy'.","q_hi":"'happy' का पर्यायवाची शब्द चुनें।","o":["sad","joyful","angry","tired"],"o_hi":["उदास","आनंदित","गुस्सा","थका हुआ"],"a":1,"exp":"'Joyful' means feeling or expressing great happiness, so it is a synonym of 'happy'.","exp_hi":"'Joyful' का अर्थ है बहुत खुशी महसूस करना या व्यक्त करना, इसलिए यह 'happy' का पर्यायवाची है।","why":["'Sad' is the opposite of happy (antonym). ('Sad' happy का विलोम है।)","'Angry' means feeling or showing strong displeasure, not happiness. ('Angry' का अर्थ है प्रबल असंतोष, खुशी नहीं।)","'Tired' means needing rest or sleep, not happy. ('Tired' का अर्थ है आराम या नींद की आवश्यकता, खुश नहीं।)"],"topic":"Vocabulary","level":1,"mode":"standard"},{"q":"Which of the following sentences uses the correct form of the verb?","q_hi":"निम्नलिखित में से किस वाक्य में क्रिया का सही रूप प्रयोग हुआ है?","o":["She has been working here since 2010.","She is working here since 2010.","She works here since 2010.","She worked here since 2010."],"o_hi":["वह 2010 से यहाँ काम कर रही है।","वह 2010 से यहाँ काम कर रही है। (is working)","वह 2010 से यहाँ काम करती है। (works)","वह 2010 से यहाँ काम करती थी। (worked)"],"a":0,"exp":"With 'since' we use present perfect continuous tense to show an action that started in the past and is still continuing.","exp_hi":"'since' के साथ present perfect continuous tense का प्रयोग होता है क्योंकि कार्य भूतकाल में शुरू होकर अब तक जारी है।","why":["'is working' present continuous है, जो since के साथ प्रयोग नहीं होता।","'works' simple present है, जो since के साथ गलत है।","'worked' simple past है, जो since के साथ गलत है।"],"topic":"Tenses","level":2,"mode":"standard"},{"q":"Identify the figure of speech in the line: 'The wind whispered through the trees.'","q_hi":"इस पंक्ति में अलंकार पहचानें: 'The wind whispered through the trees.'","o":["Personification","Simile","Metaphor","Alliteration"],"o_hi":["मानवीकरण (Personification)","उपमा (Simile)","रूपक (Metaphor)","अनुप्रास (Alliteration)"],"a":0,"exp":"The wind is given the human quality of whispering, so it is personification.","exp_hi":"हवा को फुसफुसाने का मानवीय गुण दिया गया है, इसलिए यह मानवीकरण है।","why":["Simile में 'like' या 'as' का प्रयोग होता है, यहाँ नहीं है।","Metaphor में सीधी तुलना होती है, यहाँ नहीं है।","Alliteration में एक ही ध्वनि का पुनरावृत्ति होती है, यहाँ नहीं है।"],"topic":"Figures of Speech","level":1,"mode":"standard"},{"q":"Who wrote the play 'Macbeth'?","q_hi":"'Macbeth' नाटक किसने लिखा?","o":["William Shakespeare","Charles Dickens","John Milton","Jane Austen"],"o_hi":["विलियम शेक्सपियर","चार्ल्स डिकेंस","जॉन मिल्टन","जेन ऑस्टेन"],"a":0,"exp":"Macbeth is a tragedy written by William Shakespeare.","exp_hi":"Macbeth विलियम शेक्सपियर द्वारा लिखित एक त्रासदी है।","why":["Charles Dickens उपन्यासकार थे, नाटककार नहीं।","John Milton ने 'Paradise Lost' लिखा, 'Macbeth' नहीं।","Jane Austen ने 'Pride and Prejudice' लिखा, 'Macbeth' नहीं।"],"topic":"English Literature","level":1,"mode":"standard"},{"q":"Choose the correct passive voice of: 'The teacher praised the student.'","q_hi":"निम्नलिखित का सही passive voice चुनें: 'The teacher praised the student.'","o":["The student was praised by the teacher.","The student is praised by the teacher.","The student has praised by the teacher.","The student was praising by the teacher."],"o_hi":["शिक्षक द्वारा छात्र की प्रशंसा की गई।","शिक्षक द्वारा छात्र की प्रशंसा की जाती है।","शिक्षक द्वारा छात्र की प्रशंसा की गई है।","शिक्षक द्वारा छात्र की प्रशंसा की जा रही थी।"],"a":0,"exp":"Simple past active 'praised' becomes 'was/were + past participle' in passive.","exp_hi":"सामान्य भूतकाल active 'praised' का passive 'was/were + past participle' होता है।","why":["'is praised' present passive है, जो मूल वाक्य के काल से मेल नहीं खाता।","'has praised' present perfect active है, passive नहीं।","'was praising' past continuous active है, passive नहीं।"],"topic":"Active and Passive Voice","level":2,"mode":"standard"},{"q":"Read the passage and answer: 'Rina woke up early, fed her dog, and went to school. She always helped her mother before leaving.' What does the passage tell us about Rina?","q_hi":"गद्यांश पढ़कर उत्तर दें: 'रीना जल्दी उठी, अपने कुत्ते को खाना खिलाया, और स्कूल गई। वह हमेशा जाने से पहले अपनी माँ की मदद करती थी।' यह गद्यांश रीना के बारे में क्या बताता है?","o":["She is responsible and helpful.","She is lazy and careless.","She dislikes her dog.","She never goes to school."],"o_hi":["वह जिम्मेदार और मददगार है।","वह आलसी और लापरवाह है।","वह अपने कुत्ते से नफरत करती है।","वह कभी स्कूल नहीं जाती।"],"a":0,"exp":"The passage shows Rina doing her duties and helping her mother, so she is responsible and helpful.","exp_hi":"गद्यांश में रीना अपने कर्तव्य निभाती और माँ की मदद करती दिखाई गई है, इसलिए वह जिम्मेदार और मददगार है।","why":["वह जल्दी उठती और काम करती है, इसलिए आलसी नहीं कहा जा सकता।","वह कुत्ते को खाना खिलाती है, इसलिए नफरत नहीं करती।","वह स्कूल जाती है, इसलिए 'कभी नहीं जाती' गलत है।"],"topic":"Unseen Passage","level":1,"mode":"standard"},{"q":"Which sentence correctly uses the article?","q_hi":"किस वाक्य में article का सही प्रयोग हुआ है?","o":["He is an honest man.","He is a honest man.","He is the honest man.","He is honest man."],"o_hi":["वह एक ईमानदार आदमी है। (an)","वह एक ईमानदार आदमी है। (a)","वह ईमानदार आदमी है। (the)","वह ईमानदार आदमी है। (कोई article नहीं)"],"a":0,"exp":"'Honest' begins with a vowel sound, so 'an' is used.","exp_hi":"'Honest' का उच्चारण स्वर ध्वनि से शुरू होता है, इसलिए 'an' लगता है।","why":["'a' का प्रयोग व्यंजन ध्वनि से पहले होता है, 'honest' स्वर ध्वनि से शुरू होता है।","'the' का प्रयोग निश्चितता के लिए होता है, यहाँ अनिश्चितता है।","article के बिना वाक्य अव्याकरणिक है।"],"topic":"Articles","level":1,"mode":"standard"}]}]/*__DATA_END__*/);
